// src/media-library-ui.ts
var key = "video-studio-media-library-view-v1";
var defaults = { view: "large", filter: "all", sort: "original" };
function readMediaLibraryPreferences() {
  try {
    const value2 = JSON.parse(localStorage.getItem(key) ?? "null");
    return {
      view: ["large", "small", "list"].includes(value2?.view) ? value2.view : "large",
      filter: ["all", "video", "audio", "image", "demo"].includes(value2?.filter) ? value2.filter : "all",
      sort: ["original", "name", "duration"].includes(value2?.sort) ? value2.sort : "original"
    };
  } catch {
    return { ...defaults };
  }
}
function saveMediaLibraryPreferences(value2) {
  try {
    localStorage.setItem(key, JSON.stringify(value2));
  } catch {
  }
}
function visibleMedia(assets, search2, preferences) {
  const query = search2.trim().toLocaleLowerCase();
  const result2 = assets.filter(
    (asset2) => (preferences.filter === "all" || asset2.kind === preferences.filter) && `${asset2.name}
${asset2.sourcePath ?? ""}`.toLocaleLowerCase().includes(query)
  );
  if (preferences.sort === "name")
    result2.sort((a, b) => a.name.localeCompare(b.name, "zh-CN", { numeric: true }));
  if (preferences.sort === "duration") result2.sort((a, b) => b.durationFrames - a.durationFrames);
  return result2;
}

